 * Token bucket and sliding window policy state, keyed independently per key.
 */

export function advanceBucket(policy, key, tick) {
  let state = policy.states.get(key)
  if (!state) {
    state = { tokens: policy.capacity * policy.per, lastTick: tick }
    policy.states.set(key, state)
    return state
  }
  const delta = tick - state.lastTick
  if (delta > 0n) {
    const cap = policy.capacity * policy.per
    state.tokens += policy.refill * delta
    if (state.tokens > cap) state.tokens = cap
    state.lastTick = tick
  }
  return state
}

export function bucketAllows(policy, state) {
  return state.tokens >= policy.per
}

export function bucketRecord(policy, state) {
  state.tokens -= policy.per
}

export function advanceWindow(policy, key, tick) {
  let state = policy.states.get(key)
  if (!state) {
    state = { ticks: [] }
    policy.states.set(key, state)
    return state
  }
  const threshold = tick - policy.span
  let i = 0
  while (i < state.ticks.length && state.ticks[i] <= threshold) i++
  if (i > 0) state.ticks.splice(0, i)
  return state
}

export function windowAllows(policy, state) {
  return BigInt(state.ticks.length) < policy.limit
}

export function windowRecord(state, tick) {
  state.ticks.push(tick)
}
"}

