import { parse, ParseError } from './parse.js'
import { simulate } from './simulate.js'

function readStdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  let text
  try {
    text = require('node:fs').readFileSync(0, 'utf8')
  } catch (err) {
    text = ''
  }

  let config
  try {
    config = parse(text)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const results = simulate(config)
  let out = ''

  if (mode === 'replay') {
    for (const r of results) {
      if (r.allowed) {
        out += `${r.tick} ${r.key} allow\n`
      } else {
        out += `${r.tick} ${r.key} deny ${r.deniedBy}\n`
      }
    }
  } else {
    const totals = new Map()
    let totalAllowed = 0n
    let totalDenied = 0n
    for (const r of results) {
      let t = totals.get(r.key)
      if (!t) {
        t = { allowed: 0n, denied: 0n }
        totals.set(r.key, t)
      }
      if (r.allowed) {
        t.allowed += 1n
        totalAllowed += 1n
      } else {
        t.denied += 1n
        totalDenied += 1n
      }
    }
    const keys = [...totals.keys()].sort()
    for (const key of keys) {
      const t = totals.get(key)
      out += `${key} allowed=${t.allowed} denied=${t.denied}\n`
    }
    out += `total allowed=${totalAllowed} denied=${totalDenied}\n`
  }

  process.stdout.write(out)
  process.exit(0)
}

main()
"}

